            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "To quote the only line of Gertrude Stein's which I have ever been able to understand, \"It is wonderful how I am not interested.\"", Author = "Dorothy Parker" },
