            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Writing a book for the Follies seems to be about as profitable an occupation as furnishing flannel petticoats for the showgirls.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Of course, there are many things to be said for the afternoon performance, chief among them being that it cuts in so generously on one's work.", Author = "Dorothy Parker" },
